#include <string>

using namespace std;

class Solution {
public:
    int maxVowels(string s, int k) {
        int res = 0, cnt = 0;
        for (int i = 0; i < s.size(); ++i) {
            cnt += isVowel(s[i]);
            if (i >= k) cnt -= isVowel(s[i - k]);
            res = max(res, cnt);
        }
        return res;
    }

    bool isVowel(char c) {
        return string("aeiou").find(c) != string::npos;
    }
};
